-- 云河FC 账本测试数据（2026-01 ~ 2026-12，共 100 条流水）
-- 适用：本地/测试库，先执行 schema.sql、test-data.sql 与 Flyway V17（内置 7 个账本分类）；不要在生产执行。
-- 口径：固定 id 5001-5100，重复执行会先清理本段 id 再重放；队费/赞助为收入（type=0），
--       场地/装备/活动/餐饮/其他为支出（type=1）；队费流水归属球员 1001-1015 轮流。
-- 前提：球队为“云河FC”、创建人为测试管理员 1001（13910000001）。

SET NAMES utf8mb4;
SET time_zone = '+08:00';
START TRANSACTION;

SET @team_id = (SELECT id FROM team WHERE name = '云河FC' LIMIT 1);
SET @admin_user_id = (SELECT id FROM app_user WHERE phone = '13910000001' LIMIT 1);

DELETE FROM team_ledger_entry WHERE id BETWEEN 5001 AND 5100;

;

COMMIT;
